// PDL — Espacio de trabajo behaviors (generated by scripts/build-css-index.mjs from
// design-system/registry/families.json). Pair it with css/family/workspace.
// Activates workspace and forms, navigation, overlays, data, feedback; initPDL() activates every family.
import { initAdvancedForms } from "../forms-advanced.js";
import { initFormFlows } from "../form-flow.js";
import { initSidebar, initTabs, initDisclosure } from "../runtime.js";
import { initCommandPalettes } from "../command-palette.js";
import { initMenus } from "../menus.js";
import { initOverlays } from "../overlays.js";
import { initAdvancedOverlays } from "../overlay-advanced.js";
import { initTableControls } from "../data-controls.js";
import { initDataGrids } from "../data-grid.js";
import { initSortables } from "../sortable.js";
import { initNotifications } from "../notifications.js";
import { initLoading } from "../loading.js";
import { initResizableWorkspaces } from "../workspace.js";

export function initFamily(options = {}) {
  const root = options.root ?? document;
  const instances = [
    initAdvancedForms(root),
    initFormFlows(root),
    initSidebar(root),
    initTabs(root),
    initDisclosure(root),
    initCommandPalettes(root),
    initMenus(root),
    initOverlays(root),
    initAdvancedOverlays(root),
    initTableControls(root),
    initDataGrids(root),
    initSortables(root),
    initNotifications(root),
    initLoading(root),
    initResizableWorkspaces(root),
  ];
  return {
    destroy() {
      for (const instance of instances.reverse()) instance?.destroy?.();
    }
  };
}
